// Generated by scripts/generate-stone-generator.py. Environment fluids are not consumed.
ServerEvents.recipes(event => {
    if (!Item.exists('gtceu:industrial_rock_breaker')) {
        console.warn('[Industrial rock breaker] Restart Minecraft to register the machine and recipe type.');
        return;
    }
    event.recipes.gtceu.advanced_rock_breaker('gtcsolo:stone_generator/netherrack')
        .notConsumable('minecraft:netherrack').itemOutputs('minecraft:netherrack')
        .addDataString('fluidA', 'minecraft:lava').addDataString('fluidB', 'gtceu:liquid_nether_air')
        .duration(16).EUt(GTValues.VA[GTValues.EV]);
    event.recipes.gtceu.advanced_rock_breaker('gtcsolo:stone_generator/end_stone')
        .notConsumable('minecraft:end_stone').itemOutputs('minecraft:end_stone')
        .addDataString('fluidA', 'minecraft:lava').addDataString('fluidB', 'gtceu:liquid_ender_air')
        .duration(16).EUt(GTValues.VA[GTValues.IV]);
});
